var tipuesearch = {"pages": [{"title":"About","text":"\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\r\nall: https://cycu.org/all (包羅萬象)\r\nhealth: https://cycu.org/health (健康)\r\nrecipes: https://cycu.org/recipes (食譜)\r\nclothing: https://cycu.org/clothing (衣著)\r\nliving: https://cycu.org/living (住居)\r\ntourism: https://cycu.org/tourism (旅遊)\r\nlearning: https://cycu.org/learning (學習)\r\ntech: https://cycu.org/tech (科技)\r\nart: https://cycu.org/art (藝術)\r\n易經: https://cycu.org/change (易經)\n","tags":"","url":"About.html"},{"title":"啟動","text":"\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\r\nportable_rust (Online TW) 啟動 startup.bat:\r\nportable rust (E Water)\r\n@echo off\nchcp 65001 >nul\nsetlocal ENABLEEXTENSIONS\n\nREM ==================================================\nREM Portable System Bootstrap (Rust)\nREM ==================================================\n\nREM === 虛擬磁碟代號（請勿加反斜線）===\nset DRIVE=R:\n\nREM === for Python312\nset PYTHONPATH=%DRIVE%\\Python312\\DLLs;%DRIVE%\\Python312\\Lib;%DRIVE%\\Python312\\Lib\\site-packages\nset PYTHONIOENCODING=utf-8\n\nREM === 取得 batch 所在目錄（結尾含 \\）===\nset ROOT=%~dp0\nset DATA=%ROOT%data\n\nREM === 若已存在則先解除（避免錯誤）===\nsubst %DRIVE% /D >nul 2>&1\n\nREM === 建立虛擬磁碟 ===\nsubst %DRIVE% \"%DATA%\"\n\nREM ==================================================\nREM Home / User 環境\nREM ==================================================\n\nset HOMEDRIVE=%DRIVE%\nset HOMEPATH=\\home\nset USERPROFILE=%DRIVE%\\home\nset HOME=%DRIVE%\\home\n\nREM ==================================================\nREM Git / Putty\nREM ==================================================\n\nset GIT_SSH=%DRIVE%\\PuTTY\\plink.exe\n\nREM ==================================================\nREM Rust (Portable, GNU)\nREM ==================================================\n\nset RUSTUP_HOME=%DRIVE%\\.rustup\nREM set CARGO_HOME=%DRIVE%\\.cargo\nset CARGO_HOME=C:\\cargo\nset SCITE_HOME=%DRIVE%\\wscite\nset RUSTUP_NO_UPDATE_CHECK=1\n\nREM === 強制使用 GNU toolchain ===\nset RUSTUP_TOOLCHAIN=stable-x86_64-pc-windows-gnu\n\nREM === MinGW 編譯器指定 ===\nset CC=%DRIVE%\\msys64\\ucrt64\\bin\\gcc.exe\nset CXX=%DRIVE%\\msys64\\ucrt64\\bin\\g++.exe\nset AR=%DRIVE%\\msys64\\ucrt64\\bin\\ar.exe\n\nREM === Rust linker 指定 ===\nset RUSTFLAGS=-C linker=%DRIVE%\\msys64\\ucrt64\\bin\\gcc.exe\n\nREM ==================================================\nREM MSYS2\nREM ==================================================\n\nset MSYS2=%DRIVE%\\msys64\nset CC=%DRIVE%\\msys64\\ucrt64\\bin\\gcc.exe\nset CXX=%DRIVE%\\msys64\\ucrt64\\bin\\g++.exe\nset CC_x86_64_pc_windows_gnu=%DRIVE%\\msys64\\ucrt64\\bin\\gcc.exe\nset CXX_x86_64_pc_windows_gnu=%DRIVE%\\msys64\\ucrt64\\bin\\g++.exe\n\nREM ==================================================\nREM PATH 組合\nREM ==================================================\n\nset PATH=%DRIVE%\\msys64\\ucrt64\\bin;%DRIVE%\\msys64\\usr\\bin;%CARGO_HOME%\\bin;%SCITE_HOME%;%DRIVE%\\portablegit\\bin;%DRIVE%\\Zed;%PATH%\n\nset PATH=%DRIVE%\\Python312;%DRIVE%\\Python312\\Scripts;%PATH%;%DRIVE%;%DRIVE%\\.rustup\\toolchains\\stable-x86_64-pc-windows-gnu\\bin\n\nREM ==================================================\nREM 顯示資訊\nREM ==================================================\n\ntitle Portable Rust GNU Environment (%DRIVE%)\n\necho ======================================\necho  Portable Environment Ready\necho  Mounted Drive : %DRIVE%\necho  Data Path     : %DATA%\necho  Rust Toolchain: %RUSTUP_TOOLCHAIN%\necho  MinGW GCC     : %CC%\necho  Type STOP then close window to exit\necho ======================================\necho.\n\nREM ==================================================\nREM 啟動工具\nREM ==================================================\n\nif exist \"%SCITE_HOME%\\SciTE.exe\" (\n    start \"\" /MIN \"%SCITE_HOME%\\SciTE.exe\"\n    start \"\" /MIN \"%SCITE_HOME%\\SciTE.exe\"\n)\n\nREM === 切換到虛擬磁碟 ===\n\n%DRIVE%\n\nREM ==================================================\nREM 保持命令列\nREM ==================================================\n\nstart /min \"CMD-1\" cmd /k\nstart /min \"CMD-2\" cmd /k\nstart /min \"CMD-3\" cmd /k\nstart /min \"CMD-4\" cmd /k\n\nREM ==================================================\nREM 啟動 rustcms\nREM ==================================================\n\nstart /min \"rustcms\" cmd /k \"cd /d %DRIVE%\\projects\\rustcms && cms.exe\"\n\ntimeout /t 3 /nobreak >nul\n\nstart \"\" firefox -new-tab https://localhost:5000\n\nREM ==================================================\nREM 啟動 all\nREM ==================================================\n\nstart /min \"all\" cmd /k \"cd /d %DRIVE%\\projects\\cycuorg\\all && cms.exe\"\n\ntimeout /t 3 /nobreak >nul\n\nstart \"\" firefox -new-tab https://localhost:5001\n\nREM ==================================================\nREM 啟動 art\nREM ==================================================\n\nstart /min \"art\" cmd /k \"cd /d %DRIVE%\\projects\\cycuorg\\art && cms.exe\"\n\ntimeout /t 3 /nobreak >nul\n\nstart \"\" firefox -new-tab https://localhost:5002\n\nREM ==================================================\nREM 啟動 clothing\nREM ==================================================\n\necho.\necho ======================================\necho Starting CLOTHING CMS\necho ======================================\n\nREM 確認原始目錄\n\nif not exist \"%DRIVE%\\projects\\cycuorg\\clothing\\cms.exe\" (\n    echo ERROR: clothing cms.exe not found.\n    goto CLOTHING_FIREFOX\n)\n\nREM 在原始目錄啟動，不移動、不複製\n\nstart /min \"clothing\" cmd /k \"cd /d %DRIVE%\\projects\\cycuorg\\clothing && cms.exe\"\n\nREM 等待 Port 5003，最多 30 秒\n\nset COUNT=0\n\n:WAIT_CLOTHING\n\npowershell -NoProfile -Command ^\n\"$c = New-Object System.Net.Sockets.TcpClient; try {$c.Connect('127.0.0.1',5003); exit 0} catch {exit 1} finally {$c.Dispose()}\" >nul 2>&1\n\nif not errorlevel 1 goto CLOTHING_READY\n\nset /a COUNT+=1\n\nif %COUNT% GEQ 30 goto CLOTHING_TIMEOUT\n\ntimeout /t 1 /nobreak >nul\n\ngoto WAIT_CLOTHING\n\n\n:CLOTHING_READY\n\necho.\necho [OK] CLOTHING HTTPS PORT 5003 READY.\n\ngoto CLOTHING_FIREFOX\n\n\n:CLOTHING_TIMEOUT\n\necho.\necho [WARNING] CLOTHING PORT 5003 NOT READY.\necho Please check clothing CMD window.\necho.\n\n:CLOTHING_FIREFOX\n\nREM 無論是否監聽成功，都保留 Firefox 開啟動作\n\nstart \"\" firefox -new-tab https://localhost:5003\n\nREM ==================================================\nREM 啟動 health\nREM ==================================================\n\nstart /min \"health\" cmd /k \"cd /d %DRIVE%\\projects\\cycuorg\\health && cms.exe\"\n\ntimeout /t 3 /nobreak >nul\n\nstart \"\" firefox -new-tab https://localhost:5004\n\nREM ==================================================\nREM 啟動 history\nREM ==================================================\n\nstart /min \"history\" cmd /k \"cd /d %DRIVE%\\projects\\cycuorg\\history && cms.exe\"\n\ntimeout /t 3 /nobreak >nul\n\nstart \"\" firefox -new-tab https://localhost:5005\n\nREM ==================================================\nREM 啟動 learning\nREM ==================================================\n\nstart /min \"learning\" cmd /k \"cd /d %DRIVE%\\projects\\cycuorg\\learning && cms.exe\"\n\ntimeout /t 3 /nobreak >nul\n\nstart \"\" firefox -new-tab https://localhost:5006\n\nREM ==================================================\nREM 啟動 living\nREM ==================================================\n\nstart /min \"living\" cmd /k \"cd /d %DRIVE%\\projects\\cycuorg\\living && cms.exe\"\n\ntimeout /t 3 /nobreak >nul\n\nstart \"\" firefox -new-tab https://localhost:5007\n\nREM ==================================================\nREM 啟動 recipes\nREM ==================================================\n\nstart /min \"recipes\" cmd /k \"cd /d %DRIVE%\\projects\\cycuorg\\recipes && cms.exe\"\n\ntimeout /t 3 /nobreak >nul\n\nstart \"\" firefox -new-tab https://localhost:5008\n\nREM ==================================================\nREM 啟動 tech\nREM ==================================================\n\nstart /min \"tech\" cmd /k \"cd /d %DRIVE%\\projects\\cycuorg\\tech && cms.exe\"\n\ntimeout /t 3 /nobreak >nul\n\nstart \"\" firefox -new-tab https://localhost:5009\n\nREM ==================================================\nREM 啟動 tourism\nREM ==================================================\n\nstart /min \"tourism\" cmd /k \"cd /d %DRIVE%\\projects\\cycuorg\\tourism && cms.exe\"\n\ntimeout /t 3 /nobreak >nul\n\nstart \"\" firefox -new-tab https://localhost:5010\n\nREM ==================================================\nREM 啟動 Zed\nREM ==================================================\n\nZed %DRIVE%\\projects\\rustcms\n\nREM ==================================================\nREM 結束\nREM ==================================================\n\necho.\necho ======================================\necho  ALL CMS STARTUP COMMANDS COMPLETED\necho ======================================\n\nREM 保持原本批次視窗\n\n\r\n關閉 stop.bat:\r\n@echo off\nset DRIVE=R:\n\ntaskkill /IM python.exe /F\ntaskkill /IM pythonw.exe /F\nREM taskkill /IM adb.exe /F\ntaskkill /IM scite.exe /F\ntaskkill /IM ugraf.exe /F\ntaskkill /IM webotsw.exe /F\ntaskkill /IM solvespace.exe /F\ntaskkill /IM sharex.exe /F\ntaskkill /IM leo.exe /F\ntaskkill /IM zed.exe /F\ntaskkill /IM cms.exe /F\n\necho Unmounting %DRIVE% ...\nsubst %DRIVE% /D\n\nREM 關閉 cmd 指令視窗\ntaskkill /IM cmd.exe /F\n\necho Done.\n\nEXIT\n\r\n\n","tags":"","url":"啟動.html"},{"title":"轉檔","text":"\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\r\nmd2html.7z 配合 rustcms 使用，將 Markdown 轉為 Html，並將 H1、H2、H3 標註一律轉為 H4。\n","tags":"","url":"轉檔.html"},{"title":"代理","text":"\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\r\n議題:\r\n如何使用近端 AI 代理整理 CMS 資料? 給定特定類別與主題，由 AI 代理自行尋找資料，整理納入 CMS 系統且自動提交推送到 Github 後回報結果。\n","tags":"","url":"代理.html"},{"title":"Git","text":"\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\r\n議題:\r\ngit 少量多次推送與集合大量資料後少批推送的差別何在? 比較推薦哪種方式進行資料維護？\r\n","tags":"","url":"Git.html"},{"title":"音訊","text":"\n\n\n\n\n\n\n\r\n利用電腦播放 mp3 音樂，可以透過 Voicemeeter Banana 軟體，將音訊同時送到兩個藍芽喇叭。\r\nVoicemeeter Banana 安裝後，C:\\Program Files (x86)\\VB\\Voicemeeter\\voicemeeter_x64.exe 為 standard 版，而 C:\\Program Files (x86)\\VB\\Voicemeeter\\voicemeeterpro_x64.exe 則為 pro 版。\r\n以 voicemeeterpro_x64.exe 為例，最右上方的 Hardware Out 可透過 A1、A2 與 A3 選擇後，分別對應到電腦已經連線的實體 Speaker、藍芽喇叭、藍芽耳機或實體耳機，上方 Hardware Out 左邊的 Virtual Input 則可透過電腦的設定 - 音訊 - 輸出 選擇 Voicemeeter Input。之後所有電腦的音訊輸出都會經過 Voicemeeter Input 進行轉訊，然後再由 Voicemeeter 設定的 A1、A2 與 A3 同時播放。\r\n\r\n類似能同時將電腦音訊播放到多個藍芽喇叭的功能，採用 Rust 製作: mp3_player_multi_output.zip \r\n啟動 mp3_player_multi_output 後，選擇所要播放的 mp3 檔案後，將輸出裝置設為 Voicemeeter Input，按下開始播放就可以選擇由 Voicemeeter 設定的 A1、A2 與 A3 同時播放。利用自建的 mp3 播放器，可以透過虛擬音訊等化器，配合播放環境控制輸出各頻段的增益。\r\n可選擇 mp3 或 FLAC 格式檔案，同時在多個藍芽喇叭播出: mp3_flac_player_gui.7z\r\n\r\n將 audio cd 轉為無損 FLAC: cd2flac.7z\r\n\r\n\n","tags":"","url":"音訊.html"},{"title":"flac_mp3_player","text":"\r\nhttps://github.com/cycuorg/flac_mp3_player \r\nRust src/main.rs 完整語法與程式設計解析\r\nmain.rs 是一個使用 Rust 開發的 MP3 / FLAC 多裝置同步音樂播放器。此一音樂播放程式整合了 Windows 系統音量控制、串流解碼、10 段參數式等化器（PEQ）、多個音訊輸出裝置同步播放、播放定位，以及多種 GUI 色彩主題。\r\n以 Rust 學習與實際軟體工程的角度來解說：\r\n\r\nRust 的語法、型別、所有權與借用。\r\n各種 struct、impl、trait 的設計目的。\r\nArc、AtomicBool、AtomicUsize 等多執行緒共享資料的原理。\r\n音訊解碼、串流播放與數位訊號處理的實作。\r\negui 的 GUI 事件處理與畫面更新機制。\r\n整個程式的架構、資料流與設計優缺點。\r\n\r\n這份程式相當適合作為 Rust 中階到進階的學習教材，因為它同時使用了泛型、Trait Object、閉包、迭代器、錯誤處理、智慧指標、原子變數及非同步音訊播放架構。\r\n一、整體程式架構\r\n先把近 970 行的程式分成 13 個功能模組來理解。\r\nmain.rs 架構圖\r\nmain()\r\n程式入口、視窗設定、字型與主題初始化\r\nApp / eframe::App\r\nGUI 狀態、使用者操作、播放控制、畫面更新\r\n音訊裝置管理\r\nCPAL、OutputStream、Sink\r\n音訊解碼\r\nrodio、Decoder、Source\r\n串流播放引擎\r\nGatedSource、Iterator\r\n數位音訊處理\r\nBiquad、PEQ、濾波器\r\nWindows 系統控制\r\nCOM、Audio Endpoint\r\n介面設計\r\negui、Theme、Slider\r\n各區塊在原始程式中的位置：\r\n\r\n\r\n\r\n行數\r\n主要內容\r\n\r\n\r\n\r\n\r\n1–12\r\n引入外部函式庫\r\n\r\n\r\n14–95\r\nWindows 音量控制\r\n\r\n\r\n98–200\r\n常數、色彩主題\r\n\r\n\r\n203–258\r\n播放裝置、濾波器、Source 型別\r\n\r\n\r\n259–311\r\n音訊解碼與定位\r\n\r\n\r\n312–425\r\nGatedSource 串流播放引擎\r\n\r\n\r\n427–530\r\nApp 狀態、音訊裝置、中文字型\r\n\r\n\r\n533–642\r\nApp 播放控制方法\r\n\r\n\r\n645–953\r\nGUI 介面與事件處理\r\n\r\n\r\n955–969\r\n程式入口\r\n\r\n\r\n\r\n二、Rust 的模組引用與基本語法\r\n先看第 1–12 行。\r\nuse cpal::traits::{DeviceTrait, HostTrait};\nuse eframe::egui::{self, Color32, RichText, Vec2};\nuse rodio::{Decoder, OutputStream, Sink, Source};\nuse std::fs::File;\nuse std::io::BufReader;\nuse std::path::{Path, PathBuf};\nuse std::sync::{\n    atomic::{AtomicBool, AtomicU32, AtomicU64, AtomicUsize, Ordering},\n    Arc,\n};\nuse std::time::{Duration, Instant};\r\n2.1 use 是什麼？\r\nuse 的作用是將其他模組中的型別、函式或 Trait 引入目前的作用範圍。\r\n例如：\r\nuse std::fs::File;\n\r\n之後就可以直接使用：\r\nlet file = File::open(\"music.mp3\");\n\r\n而不用每次都寫：\r\nlet file = std::fs::File::open(\"music.mp3\");\n\r\n這和 Python 的：\r\nfrom pathlib import Path import ...\n\r\n概念類似，但 Rust 的模組與型別系統更加嚴格。\r\n2.2 {} 是什麼？\r\n例如：\r\nuse std::path::{Path, PathBuf};\n\r\n代表一次引入同一個模組中的多個名稱。\r\n等同於：\r\nuse std::path::Path;\nuse std::path::PathBuf;\n\r\n2.3 self 的作用\r\nuse eframe::egui::{self, Color32, RichText, Vec2};\n\r\n這裡的 self 代表引入 egui 模組本身。\r\n所以後面可以混合使用：\r\negui::CentralPanel\nColor32\nRichText\nVec2\n\r\n這是一種很常見的 Rust 寫法。\r\n2.4 本程式引入的主要函式庫\r\n\r\n\r\n\r\n函式庫\r\n功能\r\n在程式中的用途\r\n\r\n\r\n\r\n\r\ncpal\r\n跨平台音訊裝置\r\n列出輸出裝置\r\n\r\n\r\nrodio\r\n音訊播放\r\n解碼、播放、控制 Sink\r\n\r\n\r\neframe\r\nGUI 框架\r\n建立桌面程式\r\n\r\n\r\negui\r\nGUI 元件\r\nSlider、Button、Panel\r\n\r\n\r\nanyhow\r\n錯誤處理\r\n統一回傳錯誤\r\n\r\n\r\nwindows\r\nWindows API\r\n系統音量控制\r\n\r\n\r\nrfd\r\n原生檔案對話框\r\n選擇 MP3 / FLAC\r\n\r\n\r\n\r\n另外，Arc 和 Atomic 都是 Rust 標準函式庫的功能，不需要額外安裝。\r\n三、Windows 系統音量控制：COM 與 unsafe\r\n原始程式第 14–95 行。\r\n這是整份程式中比較特殊的部分，因為它不使用 rodio 控制音量，而是直接透過 Windows API 修改作業系統的預設播放裝置音量。\r\n3.1 為什麼要區分兩種音量？\r\n本程式有兩種不同的音量概念：\r\n\r\n\r\n\r\n音量\r\n控制對象\r\n作用\r\n\r\n\r\n\r\n\r\nWindows Endpoint Volume\r\nWindows 預設播放端點\r\n影響使用該裝置的其他程式\r\n\r\n\r\nrodio Sink Volume\r\n播放器中的單一音訊串流\r\n只影響本播放器的該個輸出\r\n\r\n\r\n\r\n例如：\r\n假設 Windows 預設喇叭音量是 80%，而播放器中的某個 Sink 音量是 50%。\r\n實際輸出會同時受到兩層音量控制。\r\n因此，兩者不能混為一談。\r\n3.2 #[cfg(windows)]\r\n#[cfg(windows)]\nfn get_windows_endpoint_volume() -> anyhow::Result<f32> {\n\r\ncfg 是 Rust 的條件編譯屬性。\r\n這表示：\r\n只有在 Windows 平台編譯時，才會編譯這個函式。\r\n相反地：\r\n#[cfg(not(windows))]\nfn get_windows_endpoint_volume() -> anyhow::Result<f32> {\n    anyhow::bail!(\"Windows 音效端點音量控制僅支援 Windows\")\n}\n\r\n表示在非 Windows 平台，使用另一個同名函式。\r\n這種設計的好處是：\r\n\r\nWindows 可以直接控制系統音量。\r\nLinux、macOS 仍然可以編譯其他播放器功能。\r\n不需要在執行期間才判斷作業系統。\r\n\r\n這稱為 Conditional Compilation。\r\n3.3 anyhow::Result<f32> 是什麼？\r\n這是 Rust 常見的錯誤回傳型別。\r\n它相當於：\r\nResult<f32, anyhow::Error>\n\r\nRust 的 Result 有兩種可能：\r\nOk(value)\nErr(error)\n\r\n例如：\r\nOk(0.85)\n\r\n表示成功讀取音量，數值是 85%。\r\n而：\r\nErr(error)\n\r\n表示執行過程發生錯誤。\r\n為什麼不直接回傳 f32？\r\n因為 COM 初始化、取得音訊裝置、呼叫 Windows API 都可能失敗。\r\n使用 Result 可以讓呼叫者知道是否成功，而不必用特殊數值表示錯誤。\r\n3.4 unsafe 的用途\r\nunsafe {\n    let hr = CoInitializeEx(None, COINIT_MULTITHREADED);\n}\n\r\nRust 預設會檢查記憶體安全性。\r\n但是 Windows COM API 有一些操作需要呼叫者承擔額外的安全責任，因此部分介面被放在 unsafe 區塊中。\r\nunsafe 並不表示這段程式一定不安全。\r\n它的意思是：\r\n\r\n編譯器無法完全證明這些操作符合安全條件，必須由程式設計者負責。\r\n\r\n3.5 COM 初始化與 HRESULT\r\nlet hr = CoInitializeEx(None, COINIT_MULTITHREADED);\n\r\n這裡使用 Windows COM 的多執行緒 Apartment 模型。\r\n接著：\r\nlet initialized = if hr.0 >= 0 {\n    true\n} else if hr.0 == 0x8001_0106u32 as i32 {\n    false\n} else {\n    return Err(anyhow::anyhow!(\n        \"COM 初始化失敗，HRESULT：0x{:08X}\",\n        hr.0 as u32\n    ));\n};\r\n這裡有幾個值得學習的語法。\r\n第一：hr.0\r\nhr 是 HRESULT 型別的值，而 .0 表示存取其第一個 tuple 欄位。\r\n第二：as i32\r\n型別轉換。\r\n第三：{:08X}\r\n格式化輸出：\r\n\r\nX：十六進位大寫。\r\n8：至少八個字元。\r\n0：不足八位時前面補零。\r\n\r\n第四：return Err(...)\r\n立即結束函式，回傳錯誤。\r\n3.6 閉包 ||\r\nlet result = (|| -> anyhow::Result<f32> {\n    let enumerator =\n        CoCreateInstance::<_, IMMDeviceEnumerator>(\n            &MMDeviceEnumerator,\n            None,\n            CLSCTX_ALL\n        )?;\n\n    let device =\n        enumerator.GetDefaultAudioEndpoint(eRender, eMultimedia)?;\n\n    let endpoint: IAudioEndpointVolume =\n        device.Activate::<IAudioEndpointVolume>(CLSCTX_ALL, None)?;\n\n    Ok(endpoint.GetMasterVolumeLevelScalar()?.clamp(0.0, 1.0))\n})();\r\n這是一個非常值得理解的 Rust 語法。\r\n|| 表示不接受任何參數的閉包。\r\n例如：\r\nlet f = || {\n    println!(\"Hello\");\n};\n\nf();\n\r\n這裡的寫法：\r\n(|| -> anyhow::Result<f32> {\n    // ...\n})()\n\r\n分成兩個動作：\r\n\r\n建立一個閉包。\r\n立即呼叫這個閉包。\r\n\r\n為什麼要這樣設計？\r\n因為閉包內部使用了 ?，可以讓多個 Windows API 錯誤自動傳回 Result。\r\n但是，閉包結束後，外層仍然能執行：\r\nif initialized {\n    CoUninitialize();\n}\n\r\n這樣就能確保 COM 的初始化與解除初始化有明確的生命週期。\r\n這是一種將錯誤處理與資源清理分離的設計方式。\r\n3.7 ? 運算子\r\n例如：\r\nlet device = enumerator.GetDefaultAudioEndpoint(eRender, eMultimedia)?;\n\r\n? 的意思是：\r\n\r\n如果結果是 Ok(value)，取出 value 繼續執行。\r\n如果結果是 Err(error)，立即回傳錯誤。\r\n\r\n相當於：\r\nlet device = match enumerator.GetDefaultAudioEndpoint(eRender, eMultimedia) {\n    Ok(value) => value,\n    Err(error) => return Err(error.into()),\n};\n\r\n? 是 Rust 非常重要的語法，建議熟練掌握。\r\n四、常數與 ThemePalette：Rust 資料結構設計\r\n原始程式第 98–200 行。\r\n4.1 const\r\nconst EQ_BANDS: usize = 10;\n\nconst EQ_FREQUENCIES: [f32; EQ_BANDS] = [\n    20.0, 36.0, 65.0, 117.0, 210.0,\n    378.0, 680.0, 1224.0, 2203.0, 4000.0\n];\n\r\nconst 表示編譯期常數。\r\n這裡：\r\n[ f32; EQ_BANDS ]\n\r\n代表：\r\n\r\n陣列元素型別為 f32。\r\n陣列長度為 10。\r\n\r\n與 Vec<f32> 不同，陣列長度固定。\r\n例如：\r\nlet numbers: [i32; 3] = [10, 20, 30];\n\r\n4.2 為什麼使用 usize？\r\nconst EQ_BANDS: usize = 10;\n\r\nusize 是 Rust 用於索引、記憶體大小與集合長度的常用整數型別。\r\n例如：\r\nlet values = [10, 20, 30];\nlet index: usize = 1;\n\nprintln!(\"{}\", values[index]);\n\r\n輸出：\r\n20\n\r\n4.3 struct ThemePalette\r\n#[derive(Clone, Copy)]\nstruct ThemePalette {\n    bg: Color32,\n    card: Color32,\n    border: Color32,\n    text: Color32,\n    accent: Color32,\n}\n\r\nstruct 是結構體，用來組合多個相關資料。\r\n這裡的設計相當合理。\r\n如果不用結構體，每次更新畫面都要傳入很多顏色：\r\napply_theme(\n    bg,\n    card,\n    border,\n    text,\n    accent,\n);\n\r\n使用結構體後，只需要：\r\nlet palette = theme_palette(index);\n\r\n就可以使用：\r\npalette.bg\npalette.card\npalette.text\npalette.accent\n\r\n4.4 #[derive(Clone, Copy)]\r\n這個屬性讓 Rust 自動實作兩個 Trait。\r\n\r\nClone：允許明確複製。\r\nCopy：允許以複製方式傳遞，而不移轉所有權。\r\n\r\n因為 Color32 本身是適合複製的小型資料，所以這種設計很合適。\r\n4.5 match 表達式\r\nfn theme_palette(index: usize) -> ThemePalette {\n    match index % THEME_NAMES.len() {\n        1 => ThemePalette { /* ... */ },\n        2 => ThemePalette { /* ... */ },\n        3 => ThemePalette { /* ... */ },\n        4 => ThemePalette { /* ... */ },\n        _ => ThemePalette { /* ... */ },\n    }\n}\n\r\n這是 Rust 的模式比對。\r\nmatch 和其他語言的 switch 有點類似，但 Rust 的 match 是表達式，可以產生值。\r\n這裡：\r\nindex % THEME_NAMES.len()\n\r\n利用取餘數的方式確保索引落在 0–4。\r\n_ 是萬用模式，代表其他所有情況。\r\n4.6 閉包建立 RGB 函式\r\nlet rgb = |r, g, b| Color32::from_rgb(r, g, b);\n\r\n這是一個閉包。\r\n它等同於建立一個簡化的 RGB 轉換函式。\r\n所以：\r\nbg: rgb(13, 18, 29),\n\r\n比：\r\nbg: Color32::from_rgb(13, 18, 29),\n\r\n更簡潔。\r\n4.7 apply_theme()\r\nfn apply_theme(ctx: &egui::Context, index: usize) {\n    let p = theme_palette(index);\n    let light = index % THEME_NAMES.len() == 4;\n\n    let mut visuals = if light {\n        egui::Visuals::light()\n    } else {\n        egui::Visuals::dark()\n    };\n\n    visuals.panel_fill = p.bg;\n    visuals.window_fill = p.card;\n\n    ctx.set_visuals(visuals);\n}\r\n這段展示了 Rust 的幾個特性：\r\n\r\n&egui::Context：借用 Context，不取得所有權。\r\nlet mut：允許修改變數。\r\nif ... else：可以產生值。\r\nctx.set_visuals()：將主題套用到 GUI。\r\n\r\n值得注意：\r\nlet mut visuals\n\r\n因為接下來會修改 visuals 的多個欄位，所以必須使用 mut。\r\n五、PlayingDevice：如何管理多個音訊輸出裝置\r\n原始程式第 203–258 行。\r\n5.1 PlayingDevice 結構體\r\nstruct PlayingDevice {\n    name: String,\n    _stream: OutputStream,\n    sink: Sink,\n    volume: f32,\n}\n\r\n這個結構體代表一個正在播放音訊的輸出裝置。\r\n逐項說明：\r\n\r\n\r\n\r\n欄位\r\n型別\r\n用途\r\n\r\n\r\n\r\n\r\nname\r\nString\r\n裝置名稱\r\n\r\n\r\n_stream\r\nOutputStream\r\n維持音訊輸出串流\r\n\r\n\r\nsink\r\nSink\r\n控制該裝置的播放\r\n\r\n\r\nvolume\r\nf32\r\n該裝置的獨立音量\r\n\r\n\r\n\r\n其中最值得注意的是：\r\n_stream: OutputStream\n\r\n為什麼前面有底線？\r\nRust 通常會對未使用的變數提出警告。\r\n但是這個欄位雖然沒有直接被程式讀取，卻有非常重要的作用：維持音訊串流的生命週期。\r\n如果 OutputStream 被釋放，底層音訊輸出可能就會停止。\r\n因此，即使不直接使用它，也必須將它保存在 PlayingDevice 中。\r\n這是 Rust 中非常重要的資源管理觀念：\r\n\r\n物件的存在時間必須涵蓋它所管理的資源需要運作的時間。\r\n\r\n5.2 Biquad：數位音訊濾波器\r\n#[derive(Clone)]\nstruct Biquad {\n    b0: f32,\n    b1: f32,\n    b2: f32,\n    a1: f32,\n    a2: f32,\n    z1: f32,\n    z2: f32,\n}\n\r\n這是一個二階數位濾波器。\r\n它不是單純調整音量，而是透過數學運算改變特定頻率的響應。\r\nBiquad 是音響 EQ、低通濾波器、高通濾波器及音效處理中非常常見的基本單元。\r\n其數學原理\r\n二階 IIR 濾波器的差分方程式為：\r\n\\[ y[n]=b_0x[n]+b_1x[n-1]+b_2x[n-2] -a_1y[n-1]-a_2y[n-2] \\]\r\n其中：\r\n\r\n\\(x[n]\\)：目前輸入的音訊樣本。\r\n\\(y[n]\\)：目前輸出的音訊樣本。\r\n\\(b_0,b_1,b_2\\)：前饋係數。\r\n\\(a_1,a_2\\)：回授係數。\r\n\r\nz1、z2 則是用來保存濾波器過去的運算狀態。\r\nDefault 實作\r\nimpl Default for Biquad {\n    fn default() -> Self {\n        Self {\n            b0: 1.0,\n            b1: 0.0,\n            b2: 0.0,\n            a1: 0.0,\n            a2: 0.0,\n            z1: 0.0,\n            z2: 0.0,\n        }\n    }\n}\n\r\n這裡使用：\r\nimpl Default for Biquad\n\r\n表示為 Biquad 實作 Rust 的 Default Trait。\r\n因此可以使用：\r\nlet filter = Biquad::default();\n\r\n這組初始係數代表：\r\n\\[ y[n]=x[n] \\]\r\n也就是沒有任何濾波效果，原音直接通過。\r\nset_peaking()：設定 EQ 頻帶\r\nfn set_peaking(\n    &mut self,\n    sample_rate: f32,\n    frequency: f32,\n    q: f32,\n    gain_db: f32\n)\n\r\n這個函式用來設定 Peaking EQ 的參數。\r\n四個參數分別是：\r\n\r\n\r\n\r\n參數\r\n意義\r\n\r\n\r\n\r\n\r\n&mut self\r\n可修改目前濾波器\r\n\r\n\r\nsample_rate\r\n取樣率\r\n\r\n\r\nfrequency\r\n中心頻率\r\n\r\n\r\nq\r\n品質因數，控制頻寬\r\n\r\n\r\ngain_db\r\n增益，單位 dB\r\n\r\n\r\n\r\n例如：\r\nfilter.set_peaking(44100.0, 1000.0, 1.0, 6.0);\n\r\n代表設定：\r\n\r\n取樣率 44.1 kHz。\r\n中心頻率 1000 Hz。\r\nQ 值 1.0。\r\n增益 +6 dB。\r\n\r\n重要數學運算\r\nlet a = 10.0_f32.powf(gain_db / 40.0);\n\r\n這裡使用浮點數的 powf()，計算：\r\n\\[ A=10^{G/40} \\]\r\n其中 \\(G\\) 是增益 dB。\r\n接著：\r\nlet w0 = 2.0 * PI * frequency / sample_rate;\n\r\n換算成數位角頻率：\r\n\\[ \\omega_0=\\frac{2\\pi f_0}{f_s} \\]\r\n這些公式來自 RBJ Audio EQ Cookbook。\r\n之後程式利用 sin()、cos() 計算濾波器係數。\r\nprocess()：實際處理音訊\r\n#[inline]\nfn process(&mut self, input: f32) -> f32 {\n    let output = self.b0 * input + self.z1;\n\n    self.z1 = self.b1 * input - self.a1 * output + self.z2;\n    self.z2 = self.b2 * input - self.a2 * output;\n\n    output\n}\n\r\n這裡採用 Transposed Direct Form II。\r\n它的優點是可以用兩個狀態變數保存運算所需的歷史資料。\r\n每次傳入一個音訊樣本，就回傳一個處理後的樣本。\r\n#[inline] 是編譯器提示，希望將函式內嵌到呼叫位置，減少函式呼叫開銷。\r\n不過是否真的內嵌，仍由編譯器決定。\r\n設計上的重要觀念：\r\n濾波器不能每處理一個樣本就重新建立。\r\n因為 z1、z2 必須連續保留，才能產生正確的濾波效果。\r\n所以每個頻道都需要自己的濾波器狀態。\r\nPasted text(5).txt\r\n六、音訊解碼：Decoder、Source 與 Trait Object\r\n原始程式第 255–311 行。\r\n這個部分是整份程式的核心之一。\r\n6.1 為什麼使用串流解碼？\r\ntype StreamingDecoder = Box<dyn Source<Item = f32> + Send>;\n\r\n先解釋這個型別別名。\r\ntype 可以替複雜型別取一個容易閱讀的名稱。\r\n原本的型別是：\r\nBox<dyn Source<Item = f32> + Send>\n\r\n拆開來看：\r\n\r\n\r\n\r\n語法\r\n意義\r\n\r\n\r\n\r\n\r\nBox<T>\r\n在 Heap 配置資料的智慧指標\r\n\r\n\r\ndyn Source\r\n動態分派的 Trait Object\r\n\r\n\r\nItem = f32\r\nSource 輸出的項目型別是 f32\r\n\r\n\r\nSend\r\n可以安全地將物件移交至其他執行緒\r\n\r\n\r\n\r\n為什麼使用 dyn Source？\r\nrodio 的音訊來源可能是：\r\n\r\nDecoder。\r\n取樣率轉換後的 Source。\r\n套用音效後的 Source。\r\n跳過指定時間後的 Source。\r\n\r\n這些物件的具體型別可能不同，但都實作了 Source Trait。\r\n因此不必在程式中為每種來源建立不同的型別處理邏輯。\r\n可以統一使用：\r\nBox<dyn Source<Item = f32> + Send>\n\r\n這稱為 Trait Object。\r\n靜態分派與動態分派\r\nRust 有兩種重要的多型實作方式。\r\n\r\n\r\n\r\n方式\r\n語法\r\n特點\r\n\r\n\r\n\r\n\r\n靜態分派\r\nimpl Trait、泛型\r\n編譯期決定具體型別\r\n\r\n\r\n動態分派\r\ndyn Trait\r\n執行期透過 Trait Object 呼叫\r\n\r\n\r\n\r\n本程式使用動態分派，主要是為了讓不同音訊處理鏈可以統一存放在同一個欄位中。\r\n6.2 open_audio_decoder()\r\nfn open_audio_decoder(\n    path: &Path\n) -> anyhow::Result<Decoder<BufReader<File>>> {\n\r\n這個函式負責開啟音樂檔案並建立解碼器。\r\n注意參數：\r\npath: &Path\n\r\n這裡使用借用，而不是：\r\npath: PathBuf\n\r\n原因是函式只需要讀取路徑，不需要取得路徑的所有權。\r\nPath 和 PathBuf 的差別\r\n\r\n\r\n\r\n型別\r\n特性\r\n\r\n\r\n\r\n\r\nPath\r\n借用形式的路徑\r\n\r\n\r\nPathBuf\r\n擁有資料的路徑\r\n\r\n\r\n\r\n可以將它理解成：\r\n\r\nPath 類似 str。\r\nPathBuf 類似 String。\r\n\r\n取得副檔名\r\nlet ext = path\n    .extension()\n    .and_then(|e| e.to_str())\n    .map(|s| s.to_ascii_lowercase());\n\r\n這段使用了 Rust 的 Option 鏈式操作。\r\n逐步說明：\r\n第一步\r\npath.extension()\n\r\n取得副檔名。\r\n可能得到：\r\nSome(\"MP3\")\n\r\n也可能是：\r\nNone\n\r\n第二步\r\n.and_then(|e| e.to_str())\n\r\n將副檔名轉成字串切片。\r\n第三步\r\n.map(|s| s.to_ascii_lowercase())\n\r\n轉成小寫。\r\n因此：\r\nMP3\nMp3\nmp3\n\r\n最後都會變成：\r\nmp3\n\r\n這種寫法稱為 Option 的鏈式處理。\r\n開啟檔案與 BufReader\r\nlet open_reader = || -> anyhow::Result<BufReader<File>> {\n    let file = File::open(path)?;\n    Ok(BufReader::with_capacity(256 * 1024, file))\n};\n\r\n這裡又使用閉包。\r\n為什麼不直接寫：\r\nlet file = File::open(path)?;\n\r\n因為程式可能需要重新開啟同一個音檔。\r\n例如，先用 FLAC 專用解碼器，失敗時再使用自動偵測解碼器。\r\n所以把「開啟檔案」包裝成一個可以重複呼叫的閉包。\r\nBufReader 則提供緩衝讀取功能。\r\n256 * 1024\n\r\n代表 256 KiB 的緩衝區。\r\n這對大型 FLAC 音檔有助於減少頻繁的小型檔案讀取。\r\n6.3 match ext.as_deref()\r\nmatch ext.as_deref() {\n    Some(\"flac\") => {\n        // ...\n    }\n    Some(\"mp3\") => {\n        // ...\n    }\n    _ => {\n        // ...\n    }\n}\n\r\n這裡值得學習的是：\r\nas_deref()\n\r\n假設：\r\next: Option<String>\n\r\n呼叫：\r\next.as_deref()\n\r\n會得到：\r\nOption<&str>\n\r\n因此可以直接比較：\r\nSome(\"flac\")\n\r\n不必建立新的字串。\r\n6.4 解碼失敗後的備援機制\r\nmatch Decoder::new_flac(open_reader()?) {\n    Ok(d) => Ok(d),\n    Err(e1) => Decoder::new(open_reader()?)\n        .map_err(|e2| {\n            anyhow::anyhow!(\n                \"FLAC 解碼失敗: {e1}；自動偵測亦失敗: {e2}\"\n            )\n        }),\n}\n\r\n這裡有三種重要語法：\r\n\r\nmatch：判斷解碼是否成功。\r\nmap_err()：轉換錯誤型別或錯誤訊息。\r\nanyhow!()：建立一個錯誤物件。\r\n\r\n設計流程：\r\nFLAC 音訊檔案\r\n專用 FLAC 解碼器\r\n成功\r\n使用解碼器\r\n失敗\r\n重新開檔，自動偵測\r\n回傳 Decoder 或完整錯誤訊息\r\n這種設計比只嘗試一種解碼器更有彈性。\r\n6.5 open_stream_decoder()\r\nfn open_stream_decoder(\n    path: &Path,\n    seek_to: Duration\n) -> anyhow::Result<StreamingDecoder>\n\r\n這個函式除了開啟解碼器，還負責處理播放定位。\r\n最重要的程式：\r\nmatch decoder.try_seek(seek_to) {\n    Ok(()) => {\n        let source = decoder.convert_samples::<f32>();\n        return Ok(Box::new(source));\n    }\n    Err(_) => {\n        decoder = open_audio_decoder(path)?;\n        let source = decoder.convert_samples::<f32>()\n            .skip_duration(seek_to);\n\n        return Ok(Box::new(source));\n    }\n}\n\r\n這裡使用兩種不同的定位方式：\r\n\r\ntry_seek()：嘗試直接跳轉。\r\nskip_duration()：重新解碼並略過指定時間。\r\n\r\n第一種通常比較有效率。\r\n第二種則是備援，但對長音檔可能相當慢。\r\n另外：\r\nconvert_samples::<f32>()\n\r\n表示將解碼後的音訊樣本轉換為 f32 格式。\r\n這讓後面的 EQ 可以統一處理浮點音訊。\r\nPasted text(5).txt\r\n七、GatedSource：整份程式最重要的設計\r\n原始程式第 312–425 行。\r\n如果要真正理解這個播放器如何達成多裝置同步、即時 EQ 及同步跳轉，就必須理解 GatedSource。\r\n7.1 先看它的結構\r\nstruct GatedSource {\n    path: Arc<PathBuf>,\n    inner: StreamingDecoder,\n\n    start_gate: Arc<AtomicBool>,\n\n    seek_target: Arc<AtomicUsize>,\n    seek_generation: Arc<AtomicU64>,\n\n    seen_seek_generation: u64,\n\n    eq_gains: Arc<[AtomicU32; EQ_BANDS]>,\n    last_gains: [f32; EQ_BANDS],\n\n    filters: Vec<Vec<Biquad>>,\n\n    channels: u16,\n    sample_rate: u32,\n    duration: Option<Duration>,\n\n    cursor: usize,\n    failed: bool,\n}\n\r\n這個結構體包含整個音訊串流的運作狀態。\r\n可以分成五組：\r\n\r\n\r\n\r\n分類\r\n欄位\r\n用途\r\n\r\n\r\n\r\n\r\n音訊來源\r\npath、inner\r\n檔案路徑與解碼器\r\n\r\n\r\n同步播放\r\nstart_gate\r\n播放啟動閘門\r\n\r\n\r\n跳轉控制\r\nseek_target、seek_generation\r\n同步定位\r\n\r\n\r\nEQ 控制\r\neq_gains、last_gains、filters\r\n即時等化\r\n\r\n\r\n播放狀態\r\nchannels、sample_rate、cursor、failed\r\n音訊資訊與錯誤狀態\r\n\r\n\r\n\r\n7.2 Arc 是什麼？\r\n這是 Rust 中非常重要的智慧指標。\r\nArc<PathBuf>\n\r\nArc 全名是：\r\nAtomically Reference Counted\r\n意思是原子參照計數。\r\n假設同一個音檔要傳給三個輸出裝置：\r\n                    PathBuf\n                       |\n                      Arc\n                 _____|_____\n                |     |     |\n              裝置A  裝置B  裝置C\n\r\n三個裝置可以共享同一個路徑資料。\r\n不用複製三份 PathBuf 的內部字串資料。\r\nArc 和 Rc 的差別\r\n\r\n\r\n\r\n型別\r\n使用情境\r\n\r\n\r\n\r\n\r\nRc<T>\r\n單執行緒共享\r\n\r\n\r\nArc<T>\r\n多執行緒共享\r\n\r\n\r\n\r\n因為音訊輸出可能由不同執行緒處理，因此本程式使用 Arc。\r\n7.3 AtomicBool：播放啟動閘門\r\nstart_gate: Arc<AtomicBool>\n\r\n這是非常巧妙的設計。\r\n假設使用者同時選擇三個音訊輸出裝置。\r\n如果每個裝置建立完成後就立即開始播放，可能會出現：\r\n裝置 A：先播放\n裝置 B：晚 20 ms 播放\n裝置 C：晚 50 ms 播放\n\r\n本程式的設計是：\r\n先讓所有裝置建立 Sink，然後才一起開啟播放閘門。\r\n在每個 GatedSource 中：\r\nif !self.start_gate.load(Ordering::Acquire) {\n    return Some(0.0);\n}\n\r\n意思是：\r\n如果閘門尚未打開，就持續輸出數值為 0 的音訊樣本。\r\n因此 Sink 可以先建立、預熱，而不會提前消耗真正的音訊內容。\r\n所有裝置準備完成後：\r\nself.start_gate.store(true, Ordering::Release);\n\r\n這就是共同啟動閘門。\r\n注意：這種方式可以減少各裝置啟動時的時間差，但不代表硬體層級的絕對同步。不同音訊裝置有各自的時鐘與緩衝區，長時間播放仍可能產生時鐘漂移。\r\n7.4 Ordering：原子操作的記憶體順序\r\n程式中有：\r\nOrdering::Relaxed\nOrdering::Acquire\nOrdering::Release\nOrdering::AcqRel\n\r\n這些不是音訊功能，而是多執行緒記憶體同步機制。\r\n\r\n\r\n\r\nOrdering\r\n意義\r\n\r\n\r\n\r\n\r\nRelaxed\r\n只保證原子性，不建立跨變數同步順序\r\n\r\n\r\nAcquire\r\n確保後續讀取不越過這個讀取操作\r\n\r\n\r\nRelease\r\n確保先前操作不越過這個寫入操作\r\n\r\n\r\nAcqRel\r\n同時具有 Acquire 和 Release 特性\r\n\r\n\r\n\r\n例如：\r\nself.start_gate.store(true, Ordering::Release);\n\r\n以及：\r\nself.start_gate.load(Ordering::Acquire);\n\r\n配對使用可以建立跨執行緒的同步關係。\r\n這樣音訊執行緒在看到啟動閘門打開時，也能看到啟動前已經發布的相關狀態。\r\n7.5 AtomicUsize 和 AtomicU64：播放定位\r\nseek_target: Arc<AtomicUsize>,\nseek_generation: Arc<AtomicU64>,\n\r\n這裡使用兩個變數，而不是只用一個。\r\n用途不同：\r\n\r\nseek_target：要跳轉到哪個音訊樣本位置。\r\nseek_generation：是否出現新的跳轉命令。\r\n\r\n例如：\r\n目前 generation = 5\n使用者拖曳進度條\ntarget = 4410000\ngeneration = 6\n\r\n音訊執行緒看到 generation 從 5 變成 6，就知道需要執行新的定位。\r\n這稱為 Generation Counter（世代計數器）。\r\n比起持續輪詢整個 GUI 的狀態，這種方式更簡潔。\r\n7.6 AtomicU32 如何儲存 f32？\r\n這是另一個值得學習的 Rust 技巧。\r\neq_gains: Arc<[AtomicU32; EQ_BANDS]>\n\r\n為什麼不用：\r\nArc<[AtomicF32; EQ_BANDS]>\n\r\n因為標準 Rust 沒有提供通用的 AtomicF32。\r\n因此程式使用：\r\ngain.to_bits()\n\r\n把 f32 的位元表示轉換成 u32。\r\n讀取時：\r\nf32::from_bits(...)\n\r\n再轉換回浮點數。\r\n例如：\r\nlet value = 6.0_f32;\n\nlet bits = value.to_bits();\n\nlet restored = f32::from_bits(bits);\n\r\nrestored 仍然是 6.0。\r\n這種方式不會把浮點數轉換成整數數值，而是保留其位元表示。\r\n7.7 Vec<Vec<Biquad>> 的意義\r\nfilters: Vec<Vec<Biquad>>,\n\r\n這是二維動態陣列。\r\n其結構為：\r\nfilters\n  |\n  +-- Channel 0\n  |     +-- EQ 0\n  |     +-- EQ 1\n  |     +-- ...\n  |     +-- EQ 9\n  |\n  +-- Channel 1\n        +-- EQ 0\n        +-- EQ 1\n        +-- ...\n        +-- EQ 9\n\r\n例如立體聲：\r\n左聲道：10 個 Biquad\n右聲道：10 個 Biquad\n\r\n因此：\r\nvec![vec![Biquad::default(); EQ_BANDS]; channel_count]\n\r\n就是建立每個聲道的 10 個獨立濾波器。\r\n這非常重要。\r\n如果左右聲道共用同一個濾波器狀態，左聲道的歷史樣本可能影響右聲道的濾波結果，造成錯誤。\r\n7.8 new()：建立 GatedSource\r\nfn new(\n    path: Arc<PathBuf>,\n    channels: u16,\n    sample_rate: u32,\n    duration: Option<Duration>,\n    start_gate: Arc<AtomicBool>,\n    seek_target: Arc<AtomicUsize>,\n    seek_generation: Arc<AtomicU64>,\n    eq_gains: Arc<[AtomicU32; EQ_BANDS]>,\n) -> anyhow::Result<Self>\n\r\n這裡使用：\r\n-> anyhow::Result<Self>\n\r\nSelf 代表目前的結構體，也就是 GatedSource。\r\n因此這個函式是建構函式，成功時回傳完整的 GatedSource。\r\nSelf { ... } 的寫法\r\nlet mut source = Self {\n    path,\n    inner,\n    start_gate,\n    seek_target,\n    seek_generation,\n    seen_seek_generation,\n    eq_gains,\n    last_gains: [f32::NAN; EQ_BANDS],\n    filters: vec![\n        vec![Biquad::default(); EQ_BANDS];\n        channel_count\n    ],\n    channels: channels.max(1),\n    sample_rate,\n    duration,\n    cursor: 0,\n    failed: false,\n};\r\n這裡有兩個重要語法：\r\n欄位簡寫\r\npath,\n\r\n等同於：\r\npath: path,\n\r\n前提是欄位名稱和變數名稱相同。\r\n陣列初始化\r\n[f32::NAN; EQ_BANDS]\n\r\n表示建立十個 NaN。\r\n為什麼使用 NaN？\r\n因為第一次更新 EQ 時：\r\nif (gain - self.last_gains[band]).abs() > 0.001\n    || !self.last_gains[band].is_finite()\n\r\nNaN 不是有限數值，因此：\r\n!self.last_gains[band].is_finite()\n\r\n第一次必定成立，確保所有濾波器都會初始化。\r\n7.9 refresh_eq()：更新 EQ\r\nfn refresh_eq(&mut self) {\n    for band in 0..EQ_BANDS {\n        let gain = f32::from_bits(\n            self.eq_gains[band].load(Ordering::Relaxed)\n        );\n\n        if (gain - self.last_gains[band]).abs() > 0.001\n            || !self.last_gains[band].is_finite()\n        {\n            for channel_filters in &mut self.filters {\n                channel_filters[band].set_peaking(\n                    self.sample_rate as f32,\n                    EQ_FREQUENCIES[band],\n                    1.0,\n                    gain,\n                );\n            }\n\n            self.last_gains[band] = gain;\n        }\n    }\n}\n\r\n這段最重要的觀念是：\r\nGUI 修改 EQ 時，不直接操作音訊執行緒中的濾波器，而是更新共享參數。\r\n音訊執行緒自行讀取參數，並更新本地濾波器。\r\n這是一種 Producer / Consumer 設計：\r\n\r\nProducer：GUI，產生新的 EQ 參數。\r\nConsumer：音訊來源，讀取 EQ 參數並處理音訊。\r\n\r\n而且只有增益真正改變時，才重新計算係數。\r\n這樣能減少不必要的運算。\r\n7.10 apply_pending_seek()：同步跳轉\r\nfn apply_pending_seek(&mut self) {\n    let generation =\n        self.seek_generation.load(Ordering::Acquire);\n\n    if generation == self.seen_seek_generation {\n        return;\n    }\n\r\n這裡比較目前的 generation 和上次處理的 generation。\r\n如果相同，表示沒有新命令。\r\n如果不同，就讀取：\r\nlet sample_index =\n    self.seek_target.load(Ordering::Acquire);\n\r\n接著將樣本位置轉換成秒數：\r\nlet seconds = sample_index as f64\n    / self.sample_rate.max(1) as f64\n    / self.channels.max(1) as f64;\n\r\n這裡必須理解音訊樣本的排列方式。\r\n假設：\r\n\r\n取樣率：44100 Hz。\r\n聲道數：2。\r\n目標樣本索引：441000。\r\n\r\n那麼：\r\n\\[ t=\\frac{441000}{44100\\times2}=5 \\]\r\n即定位到約 5 秒。\r\n為什麼除以聲道數？\r\n因為程式使用的是交錯排列的音訊樣本：\r\n左1、右1、左2、右2、左3、右3……\n\r\n因此每秒總樣本數是：\r\n\\[ 44100\\times2=88200 \\]\r\n接下來：\r\nmatch open_stream_decoder(self.path.as_path(), target) {\n    Ok(decoder) => {\n        self.inner = decoder;\n        self.cursor = sample_index;\n        // ...\n    }\n    Err(error) => {\n        eprintln!(\"音訊跳轉失敗：{error}\");\n        self.failed = true;\n    }\n}\n\r\n成功時：\r\n\r\n更換解碼器。\r\n更新游標。\r\n重設各濾波器的歷史狀態。\r\n清除錯誤旗標。\r\n\r\n為什麼重設 z1 和 z2？\r\n因為跳轉後的音訊已經不是原本連續的時間序列。\r\n若沿用跳轉前的濾波器狀態，可能產生不正確的瞬態響應。\r\n7.11 Iterator Trait：讓音訊來源逐個輸出樣本\r\n這是整份程式另一個非常重要的 Rust 語法。\r\nimpl Iterator for GatedSource {\n    type Item = f32;\n\n    fn next(&mut self) -> Option<Self::Item> {\n\r\n表示：\r\n為 GatedSource 實作 Iterator Trait。\r\ntype Item = f32 表示每次迭代產生一個 f32。\r\nnext() 的回傳值：\r\nOption<f32>\n\r\n有兩種可能：\r\n\r\nSome(sample)：還有音訊樣本。\r\nNone：音訊串流結束。\r\n\r\n真正的音訊處理流程\r\nlet channel = self.cursor % self.channels as usize;\n\nif channel == 0 {\n    self.refresh_eq();\n}\n\nlet mut sample = self.inner.next()?;\n\nfor filter in &mut self.filters[channel] {\n    sample = filter.process(sample);\n}\n\nself.cursor = self.cursor.saturating_add(1);\n\nSome(sample)\n\r\n逐步理解：\r\n\r\n根據 cursor 判斷目前樣本屬於哪個聲道。\r\n每次開始新的聲道組合時，檢查 EQ 是否更新。\r\n從解碼器取得下一個音訊樣本。\r\n依序通過該聲道的十個 Biquad。\r\n增加樣本索引。\r\n回傳處理後的樣本。\r\n\r\n例如立體聲：\r\n樣本 0 → 左聲道 → EQ 0~9\n樣本 1 → 右聲道 → EQ 0~9\n樣本 2 → 左聲道 → EQ 0~9\n樣本 3 → 右聲道 → EQ 0~9\n\r\n? 在 Iterator 中的意義\r\nlet mut sample = self.inner.next()?;\n\r\n如果解碼器回傳：\r\nSome(value)\n\r\n就取得 value。\r\n如果解碼器回傳：\r\nNone\n\r\n則目前的 next() 也立即回傳 None。\r\n因此整個音訊來源自然結束。\r\nsaturating_add()\r\nself.cursor = self.cursor.saturating_add(1);\n\r\n這是防止整數溢位的寫法。\r\n一般的：\r\nself.cursor += 1;\n\r\n在極端情況下可能發生整數溢位。\r\nsaturating_add() 在超過型別上限時會停留在最大值。\r\n對於長時間運作的音訊串流，這是較謹慎的寫法。\r\n7.12 為什麼還要實作 Source Trait？\r\nimpl Source for GatedSource {\n    fn current_frame_len(&self) -> Option<usize> {\n        None\n    }\n\n    fn channels(&self) -> u16 {\n        self.channels\n    }\n\n    fn sample_rate(&self) -> u32 {\n        self.sample_rate\n    }\n\n    fn total_duration(&self) -> Option<Duration> {\n        self.duration\n    }\n}\n\r\nIterator 只告訴 rodio：\r\n如何逐個取得音訊樣本。\r\nSource 則額外提供音訊格式資訊：\r\n\r\n聲道數。\r\n取樣率。\r\n播放時間。\r\n目前音框長度。\r\n\r\n因此 GatedSource 就能被當作 rodio 的一般音訊來源使用。\r\nPasted text(5).txt\r\n八、App：整個 GUI 的狀態管理\r\n原始程式第 427–530 行。\r\n這裡開始進入 GUI 與音訊引擎之間的整合。\r\n8.1 App 結構體\r\nstruct App {\n    selected_file: Option<PathBuf>,\n    devices: Vec<String>,\n    selected: Vec<bool>,\n    device_volumes: Vec<f32>,\n\n    is_playing: bool,\n    status: String,\n    volume: f32,\n\n    playing: Vec<PlayingDevice>,\n\n    sample_rate: u32,\n    channels: u16,\n    duration: Duration,\n    position_offset: Duration,\n    playback_started: Option<Instant>,\n\n    start_gate: Arc<AtomicBool>,\n    seek_target: Arc<AtomicUsize>,\n    seek_generation: Arc<AtomicU64>,\n    eq_shared: Arc<[AtomicU32; EQ_BANDS]>,\n\n    eq_gains: [f32; EQ_BANDS],\n    theme_index: usize,\n}\n\r\n這個結構體是整個應用程式的中心。\r\n它負責儲存：\r\n\r\n使用者選擇的音樂。\r\n可用音訊裝置。\r\n各裝置的選取狀態。\r\n各裝置的音量。\r\n播放狀態。\r\n播放進度。\r\nEQ 參數。\r\nGUI 主題。\r\n與音訊執行緒共享的控制資訊。\r\n\r\n為什麼 selected 和 devices 分開？\r\ndevices: Vec<String>,\nselected: Vec<bool>,\n\r\n假設：\r\ndevices = [\n    \"Speakers\",\n    \"Bluetooth Headphones\",\n    \"HDMI Audio\"\n];\n\r\n而：\r\nselected = [\n    true,\n    false,\n    true\n];\n\r\n代表：\r\n\r\n\r\n\r\n裝置\r\n是否選取\r\n\r\n\r\n\r\n\r\nSpeakers\r\n是\r\n\r\n\r\nBluetooth Headphones\r\n否\r\n\r\n\r\nHDMI Audio\r\n是\r\n\r\n\r\n\r\n這是使用平行陣列的設計。\r\n兩個陣列的索引必須保持一致。\r\n優點是容易操作，缺點是資料同步需要特別小心。\r\n8.2 Option 型別\r\nselected_file: Option<PathBuf>\n\r\n代表目前可能有音樂檔案，也可能沒有。\r\nNone\n\r\n代表尚未選擇。\r\nSome(path)\n\r\n代表已選擇檔案。\r\n這比使用空字串或特殊路徑來表示「沒有檔案」更安全。\r\n8.3 Duration 與 Instant\r\nduration: Duration,\nposition_offset: Duration,\nplayback_started: Option<Instant>,\n\r\n這三個型別很重要。\r\n\r\n\r\n\r\n型別\r\n用途\r\n\r\n\r\n\r\n\r\nDuration\r\n表示時間長度\r\n\r\n\r\nInstant\r\n表示單調遞增的時間點\r\n\r\n\r\n\r\n| Option\n","tags":"","url":"flac_mp3_player.html"},{"title":"定時澆水","text":"\n\n\n\n\n\n\r\nA01 小陽台自動澆水系統\r\nEZ-Life DMA中文自動澆水定時器\r\nOrbit 62061Z 單出口電池式澆水定時器\r\nHunter NODE 電池式灌溉控制器\r\nNodeMCU-32S ESP32 開發板\r\n才嘉科技 DC12V 2分常閉電磁閥\r\n才嘉科技 DC12V 4分常閉電磁閥\r\nDIY_LAB 8孔可調式滴頭\n","tags":"","url":"定時澆水.html"}]};
